// FUNCTION: SWBF2 0x006d96a0
void RedVariableWidthFont::CreateCustom(const CustomFontData& cfd)
{
    m_crcName = cfd.nameHash_;
    m_uiNumGlyphs = (unsigned short)cfd.numGlyphs_;
    m_uiHeight = (unsigned char)cfd.glyphHeight_;
    m_iAscent = 0;
    m_iDescent = 0;
    m_uiNumTextures = (unsigned char)cfd.numTextures_;

    if (m_apTextures)
    {
        RedFreeToHeap(__RedCurrHeap, m_apTextures, 0);
    }
    m_apTextures = (RedTexture**)RedAllocFromHeap(
        __RedCurrHeap, (unsigned int)m_uiNumTextures * 4, 0);
    for (unsigned int i = 0; i < (unsigned int)m_uiNumTextures; i++)
    {
        m_apTextures[i] = 0;
    }

    if (m_aGlyphs)
    {
        RedFreeToHeap(__RedCurrHeap, m_aGlyphs, 0);
    }
    m_aGlyphs = (Glyph*)RedAllocFromHeap(
        __RedCurrHeap, (unsigned int)m_uiNumGlyphs * sizeof(Glyph), 0);

    m_uiNumRanges = 0;
    unsigned short uiPrev = 0;
    for (unsigned short i = 0; i < m_uiNumGlyphs; i++)
    {
        Glyph& g = m_aGlyphs[i];
        g = cfd.glyphs_[i];

        const unsigned char uiWidth = g.width;
        g.left = 0;
        g.top = 0;
        g.right = uiWidth;
        g.bottom = uiWidth;
        g.uLeft = 0.0f;
        g.uRight = 1.0f;
        g.vTop = 0.0f;
        g.vBottom = 1.0f;

        if (m_uiNumRanges == 0)
        {
            m_uiNumRanges = 1;
        }
        else if ((unsigned int)g.value > (unsigned int)(unsigned short)(uiPrev + 1))
        {
            m_uiNumRanges++;
        }

        uiPrev = g.value;
    }

    if (m_aRanges)
    {
        RedFreeToHeap(__RedCurrHeap, m_aRanges, 0);
    }
    m_aRanges = (Range*)RedAllocFromHeap(
        __RedCurrHeap, m_uiNumRanges * sizeof(Range), 0);

    int iRange = -1;
    uiPrev = 0;
    for (unsigned short i = 0; i < m_uiNumGlyphs; i++)
    {
        const Glyph& g = m_aGlyphs[i];
        if (iRange == -1)
        {
            iRange = 0;
            m_aRanges[0].first = g.value;
        }
        else if ((unsigned int)g.value > (unsigned int)(unsigned short)(uiPrev + 1))
        {
            m_aRanges[iRange].last = uiPrev;
            iRange++;
            m_aRanges[iRange].first = g.value;
        }
        uiPrev = g.value;
    }
    m_aRanges[iRange].last = uiPrev;
}

// FUNCTION: SWBF2 0x006d9210
RedFixedWidthFont::RedFixedWidthFont(const char* pcName, const RedTexture* pTexture,
                                     unsigned char uiCharWidth, unsigned char uiCharHeight,
                                     char iAscent, unsigned int uiMaxGlyphs)
{
    m_iAscent = (char)(uiCharHeight - iAscent);
    m_iDescent = iAscent;
    m_pTexture = pTexture;
    m_uiHeight = uiCharHeight;

    const unsigned int uiPerRow = pTexture->m_uiWidth / uiCharWidth;
    const float fU = 1.0f / (float)pTexture->m_uiWidth;
    const float fV = 1.0f / (float)pTexture->m_uiHeight;

    unsigned int uiCount = (pTexture->m_uiHeight / uiCharHeight) * uiPerRow;
    m_uiNumGlyphs = (unsigned short)uiCount;
    if (m_uiNumGlyphs != 0 && uiMaxGlyphs < (unsigned int)m_uiNumGlyphs)
    {
        m_uiNumGlyphs = (unsigned short)uiMaxGlyphs;
    }

    m_aGlyphs = new Glyph[m_uiNumGlyphs];
    memset(m_aGlyphs, 0, (unsigned int)m_uiNumGlyphs * sizeof(Glyph));

    for (unsigned int i = 0; i < (unsigned int)m_uiNumGlyphs; i++)
    {
        Glyph& g = m_aGlyphs[i];

        const unsigned int uiCol = i % uiPerRow;
        const unsigned int uiRow = i / uiPerRow;
        const unsigned int uiX = uiCharWidth * uiCol + 1;
        const unsigned int uiY = m_uiHeight * uiRow + 1;

        g.value = (unsigned short)(0x20 + i);
        g.width = (unsigned char)(uiCharWidth - 4);
        g.texnum = 0;
        g.left = 0;
        g.right = (unsigned char)(uiCharWidth - 2);
        g.top = 0;
        g.bottom = (unsigned char)(m_uiHeight - 1);

        g.uLeft = (float)uiX * fU;
        g.uRight = (float)(uiCharWidth - 1 + uiX) * fU;
        g.vTop = (float)uiY * fV;
        g.vBottom = (float)(m_uiHeight - 1 + uiY) * fV;
    }

    m_pNextFont = s_SpecialFont;
    m_crcName = PblHash(pcName);

    if (!s_fontHashTable.Find(m_crcName))
    {
        if (s_fontHashTable.Store(m_crcName, this))
        {
            s_fontHashTableNumEntries++;
        }
    }
}

