// FUNCTION: SWBF2 0x006d9aa0
const RedTexture* RedFixedWidthFont::GetTexture(unsigned char uiTexture) const
{
    if (m_pNextFont && uiTexture >= 0x80)
    {
        return m_pNextFont->GetTexture((unsigned char)(uiTexture - 0x80));
    }
    return m_pTexture;
}

// FUNCTION: SWBF2 0x006d9ad0
const RedTexture* RedVariableWidthFont::GetTexture(unsigned char uiTexture) const
{
    if (uiTexture >= 0x80)
    {
        uiTexture -= 0x80;
        if (m_pNextFont)
        {
            return m_pNextFont->GetTexture(uiTexture);
        }
    }
    if (m_pNextFont && uiTexture >= m_uiNumTextures)
    {
        return m_pNextFont->GetTexture((unsigned char)(uiTexture - m_uiNumTextures));
    }
    return m_apTextures[uiTexture];
}

// FUNCTION: SWBF2 0x006d9b20
void RedFont::Init()
{
    s_SpecialFont = new RedVariableWidthFont;
    s_SpecialFont->SetNextFont(0);
    s_SpecialFont->CreateCustom(GetMagicCharFontData());

    IDirect3DTexture9* pTexture;
    RedRenderer::pcGetDevice()->CreateTexture(0x100, 0x80, 1, 0, D3DFMT_A4R4G4B4,
                                             D3DPOOL_MANAGED, &pTexture, 0);

    D3DLOCKED_RECT lr;
    pTexture->LockRect(0, &lr, 0, 0);
    memcpy(lr.pBits, s_pcSystemFontBitmapData, 0x10000);
    pTexture->UnlockRect(0);

    s_systemFontTexture = new RedTexture(pTexture, 0x274E1290);
    pTexture->Release();

    new RedFixedWidthFont("systemfont", s_systemFontTexture, 0x10, 0x15, 0x12, 0xa0);
}

// FUNCTION: SWBF2 0x006d9db0
void RedFont::Read(PblFileChunk& chunk)
{
    RedVariableWidthFont* pFont = new RedVariableWidthFont;
    pFont->SetNextFont(s_SpecialFont);
    pFont->Read(chunk);

    if (s_fontHashTable.Find(pFont->m_crcName))
    {
        delete pFont;
        return;
    }

    if (s_fontHashTable.Store(pFont->m_crcName, pFont))
    {
        s_fontHashTableNumEntries++;
    }
}

// FUNCTION: SWBF2 0x006d9e30
void RedVariableWidthFont::Read(PblFileChunk& chunk)
{
    char acName[256];

    while (chunk.HasMoreChildren())
    {
        PblFileChunk child = chunk.ReadNextChild();
        switch (child._iId)
        {
        case 0x444F4246u:
        {
            if (m_aGlyphs)
            {
                RedFreeToHeap(__RedCurrHeap, m_aGlyphs, 0);
            }
            m_aGlyphs = (Glyph*)RedAllocFromHeap(
                __RedCurrHeap, (unsigned int)m_uiNumGlyphs * sizeof(Glyph), 0);

            m_uiNumRanges = 0;
            unsigned short uiPrev = 0;
            for (unsigned short i = 0; i < m_uiNumGlyphs; i++)
            {
                Glyph& g = m_aGlyphs[i];
                g.value = child._pFile->Read16();
                g.texnum = child._pFile->Read8();
                g.width = child._pFile->Read8();
                g.left = child._pFile->Read8();
                g.right = child._pFile->Read8();
                g.top = child._pFile->Read8();
                g.bottom = child._pFile->Read8();
                g.uLeft = child._pFile->ReadFloat();
                g.uRight = child._pFile->ReadFloat();
                g.vTop = child._pFile->ReadFloat();
                g.vBottom = child._pFile->ReadFloat();

                if (m_uiNumRanges == 0)
                {
                    m_uiNumRanges = 1;
                }
                else if (g.value > uiPrev + 1)
                {
                    m_uiNumRanges++;
                }

                uiPrev = g.value;
            }
            break;
        }

        case 0x44414548u:
            m_uiNumGlyphs = child._pFile->Read16();
            m_uiNumTextures = child._pFile->Read8();
            m_uiHeight = child._pFile->Read8();
            m_iAscent = child._pFile->Read8();
            m_iDescent = child._pFile->Read8();
            break;

        case 0x454D414Eu:
            child.ReadString(acName, 256);
            m_crcName = PblHash(acName);
            PblTraceP("Font [%s]\tHash 0x%08x\n", acName, m_crcName);
            break;

        case 0x58455446u:
        {
            if (m_apTextures)
            {
                RedFreeToHeap(__RedCurrHeap, m_apTextures, 0);
            }
            m_apTextures = (RedTexture**)RedAllocFromHeap(
                __RedCurrHeap, (unsigned int)m_uiNumTextures * 4, 0);

            for (unsigned char i = 0; i < m_uiNumTextures; i++)
            {
                PblFileChunk name = child.ReadNextChild();
                name.ReadString(acName, 256);
                const unsigned int uiHash = PblHash(acName);

                PblFileChunk texture = child.ReadNextChild();
                RedTexture::Read(texture);

                m_apTextures[i] = RedTexture::s_textureHashTable.Find(uiHash);
            }
            break;
        }
        }
    }

    if (m_aRanges)
    {
        RedFreeToHeap(__RedCurrHeap, m_aRanges, 0);
    }
    m_aRanges = (Range*)RedAllocFromHeap(__RedCurrHeap, m_uiNumRanges * sizeof(Range), 0);

    int iRange = -1;
    unsigned short uiPrev = 0;
    for (unsigned short i = 0; i < m_uiNumGlyphs; i++)
    {
        const Glyph& g = m_aGlyphs[i];
        if (iRange == -1)
        {
            iRange = 0;
            m_aRanges[0].first = g.value;
        }
        else if (g.value > uiPrev + 1)
        {
            m_aRanges[iRange].last = uiPrev;
            iRange++;
            m_aRanges[iRange].first = g.value;
        }
        uiPrev = g.value;
    }
    m_aRanges[iRange].last = uiPrev;
}

